#include<iostream>
#include<bits/stdc++.h>
using namespace std;
typedef long long LL;
const int MOD=1000000007;
const int maxn=1000007;
LL P,K;
LL vis[maxn];
LL num[maxn];
LL getnum(int pos)
{
    LL tep=(num[pos]*pos)%MOD;
    tep=(tep+1)%MOD;
    LL re=1;
    for(int i=1;i<=num[pos];i++)
        re=(re*tep)%MOD;
    return re;
}
int main()
{
    cin >> P>>K;
    memset(vis,0,sizeof(vis));
    memset(num,0,sizeof(num));
    if(K==0){
        LL tepre=1;
        for(int i=1;i<P;i++)
            tepre=(tepre*P)%MOD;
        cout<<tepre<<endl;
        return 0;
    }
    if(K==1){
        long long tepre=1;
        for(int i=1;i<=P;i++)
            tepre=(tepre*P)%MOD;
        cout<<tepre<<endl;
        return 0;
    }
   // cout<<"!!!!"<<endl;
    for(int i=0;i<P;i++){
        if(!vis[i]){
            LL tepnum=0;
            LL pos=i;
            while(!vis[pos]){
                vis[pos]=1;
                tepnum++;
                pos=(K*pos)%P;
            }
            num[tepnum]++;
        }
    }
    //cout<<"!!!!"<<endl;
    LL re=1;
    for(int i=2;i<P;i++){
        if(num[i]){
            re=(re*getnum(i))%MOD;
        }
    }
    //cout<<getnum(3)<<endl;
    cout<<re<<endl;
    return 0;
}


